    rows.forEach(([id, lab, ic, pri], i) => { button(id, lab, ic, W / 2, cy + off + 84 + i * (bh + gap), bw, bh, !!pri, 0.1 + i * 0.05); if (id === 'app') { const r = engine.screenBtns.at(-1); if (r?.id === 'app') engine.appRect = r; } });
