  const head = L ? `Level ${scene.level} complete` : win ? 'You win!' : 'Game over', hc = good ? TH.good : TH.bad;
  const score = Math.floor(scene.vars.score || 0), shown = Math.round(score * Ease.outCubic(P(0.35, 0.9)));
