  const d = Math.max(0.01, +p.duration || 1), three = is3D(e), A = (k, def) => (Number.isFinite(+p[k]) && p[k] !== '' ? +p[k] : def);
  const vec = { x: +p.x || 0, y: +p.y || 0, ...(three ? { z: +p.z || 0 } : {}) }, rk = three ? 'ry' : 'rz';
