      update(e, dt, s) { if ((p.playOn === 'tap' || toggle) && e.visible && s.engine.input.taps.some((t) => hitTest(s, e, t.x, t.y))) play(e, s); },
      collide(e, other, s) { if (p.playOn === 'touched by tag' && other.has(p.tag)) play(e, s); },
