          const ck = checkKey();
          if (ck && t.x < G.b.x + 8 + G.rh * 0.75) { checkAt[row.r.id] = now(); s.engine.data.update(p.collection, row.r.id, { [ck]: !truthy(row.r[ck]) }); continue; }
          openRecord(s, p.collection, row.r);
