      face(e, dx, dy); cool = Math.max(0.2, +p.attackEvery || 0.8); self.attacked = true; self.acted = true;
      const dmg = Math.max(0, +p.damage || 0) + (+e.data.equipDamage || 0), three = is3D(e);
      const hit = () => { if (!o.dead) gridHurt(s, o, dmg, e); };
