        sq.fx.push({ k: 'shot', x0: e.x, y0: three ? e.z : e.y, x1: o.x, y1: three ? o.z : o.y, gy, t: s.time, look: p.shot, col: p.shot === 'magic bolt' ? '#b388ff' : '#ffe082' });
