        if (list.some((t) => ['tap', 'doubleTap', 'longPress'].includes(t.event?.type) || (t.event?.type === 'node' && ['tap', 'onDoubleTap', 'onLongPress', 'onDragThis'].includes(t.event.node)))) (s.tapTargets ||= new Set()).add(e); // the joystick leaves these alone
